import csv,json
occ3={'J01':3,'J02':4,'J03':1,'J04':3,'J05':3,'J06':1,'J07':5,'J08':3,'J09':0,'J10':3,'J11':3,'J12':1}
sel={k.split('-')[0]+'-'+k.split('-')[1]:v for k,v in json.load(open('scratch/day7_sel.json')).items()}
sel={(int(k.split('-')[0]),k.split('-')[1]):v for k,v in sel.items()}
# 续办券
cp=[('J01','J02',5,1,9,11),('J02','J01',6,2,9,10),('J03','J04',4,3,10,11),('J04','J03',5,1,9,11),
('J05','J06',6,2,9,10),('J06','J05',4,3,9,11),('J07','J08',5,1,10,11),('J08','J07',6,2,9,10),
('J09','J10',5,3,9,11),('J10','J09',4,1,9,11),('J11','J12',6,2,10,10),('J12','J11',5,3,9,11)]
# 历史合同（第7日划转单：全部 生效9-末日12）
seal=[('T37','J01','J07','接续',7,4),('T19','J04','J07','独立',7,4),('T52','J03','J11','独立',6,3),('T08','J07','J11','接续',6,3),
('T41','J06','J01','接续',6,4),('T26','J09','J01','独立',6,4),('T63','J08','J10','独立',6,3),('T14','J12','J10','接续',6,3)]
def coupon(day):
    v={}
    for b,s,base,upl,e,l in cp:
        if e<=day<=l: v[b]=min(upl,max(0,base-occ3[s]))
    return v
def contract(day):
    v={}
    for no,b,s,kind,g,cap in seal:
        v.setdefault(b,[]).append((no,kind,min(cap,max(0,g-occ3[s]))))
    return v
def combine(day):
    c=coupon(day); ct=contract(day); out={}; det={}
    for k in occ3:
        ck=c.get(k,0); lst=ct.get(k,[])
        ind=sum(x[2] for x in lst if x[1]=='独立'); jx=[x[2] for x in lst if x[1]=='接续']
        if jx: tot=ind+max([ck]+jx); d=f"券{ck}/接续{max(jx)}→{max([ck]+jx)}"+(f"+独立{ind}" if ind else "")
        else: tot=ind+ck; d=f"券{ck}"+(f"+独立{ind}" if ind else "")
        out[k]=tot; det[k]=d
    return out,det
